import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"Full System Backup & Restore (.wfam)","description":"","frontmatter":{},"headers":[],"relativePath":"user/backup_restore.md","filePath":"user/backup_restore.md"}'),n={name:"user/backup_restore.md"};function o(i,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="full-system-backup-restore-wfam" tabindex="-1">Full System Backup &amp; Restore (<code>.wfam</code>) <a class="header-anchor" href="#full-system-backup-restore-wfam" aria-label="Permalink to &quot;Full System Backup &amp; Restore (`.wfam`)&quot;">​</a></h1><p>WealthFam provides a complete, portable <strong>System Backup &amp; Restore</strong> workflow under <strong>Settings → Backup &amp; Restore</strong>. You can export your entire family workspace into a single <code>.wfam</code> file before migrating servers, resetting an environment, or deleting an account—and restore it months later without depending on old server encryption keys or database IDs.</p><hr><h2 id="who-can-use-backup-restore" tabindex="-1">Who Can Use Backup &amp; Restore <a class="header-anchor" href="#who-can-use-backup-restore" aria-label="Permalink to &quot;Who Can Use Backup &amp; Restore&quot;">​</a></h2><ul><li><strong>Allowed</strong>: <code>OWNER</code> and <code>ADULT</code> family members.</li><li><strong>Restricted</strong>: <code>CHILD</code> and <code>GUEST</code> accounts cannot export, inspect, or import system backups.</li></ul><hr><h2 id="what-is-included-in-a-wfam-backup" tabindex="-1">What Is Included in a <code>.wfam</code> Backup <a class="header-anchor" href="#what-is-included-in-a-wfam-backup" aria-label="Permalink to &quot;What Is Included in a `.wfam` Backup&quot;">​</a></h2><p>A <code>.wfam</code> archive captures all family-scoped data across WealthFam:</p><ul><li><strong>Family Circle &amp; Workspace Settings</strong>: Tenant name, member profiles (email, name, DOB, PAN, phone, avatar, role), and workspace settings. <em>(Login passwords, active sessions, and server encryption keys are never exported.)</em></li><li><strong>Banking &amp; Financial Instruments</strong>: Accounts, balance snapshots, credit card details, fixed &amp; recurring deposits, provident funds (EPF/PPF/NPS), loans, and expense groups.</li><li><strong>Ledger &amp; Automation</strong>: All transactions (including transfer links and location coordinates), categories &amp; subcategories, categorization rules, rule hit stats, budgets, and recurring transactions.</li><li><strong>Investments &amp; Goals</strong>: Mutual fund holdings, orders, SIPs, referenced scheme metadata, investment goals, and linked goal assets.</li><li><strong>Statements &amp; Document Vault</strong>: Statements, statement transactions, password cache, Vault folders, documents, version history, and actual Vault files (PDFs, receipts, thumbnails).</li><li><strong>Ingestion &amp; Notifications</strong>: Email sync configurations, sync logs, pending triage transactions, unparsed messages, custom parsing patterns, spam filters, ignored patterns, merchant aliases, and alerts.</li></ul><hr><h2 id="exporting-a-backup" tabindex="-1">Exporting a Backup <a class="header-anchor" href="#exporting-a-backup" aria-label="Permalink to &quot;Exporting a Backup&quot;">​</a></h2><ol><li>Open <strong>Settings → Backup &amp; Restore</strong>.</li><li>Keep <strong>Encrypt backup with a custom passphrase</strong> enabled (recommended, enabled by default) and enter a strong passphrase (at least 8 characters) in both passphrase fields. <ul><li>Inside the <code>.wfam</code> container, server-specific encryption is removed so the backup remains portable across servers. The outer <code>.wfam</code> file is then encrypted with your custom passphrase using <strong>PBKDF2-HMAC-SHA256 + AES-256-GCM</strong>.</li><li>If you explicitly disable encryption, the <code>.wfam</code> file is written without a passphrase lock—store it only in an encrypted location.</li></ul></li><li>Choose whether to include <strong>Document Vault files &amp; statements</strong> (enabled by default).</li><li>Click <strong>Download <code>.wfam</code> Backup</strong> and store both the file and your passphrase safely.</li></ol><hr><h2 id="restoring-a-backup-even-months-later-or-on-a-new-server" tabindex="-1">Restoring a Backup (Even Months Later or on a New Server) <a class="header-anchor" href="#restoring-a-backup-even-months-later-or-on-a-new-server" aria-label="Permalink to &quot;Restoring a Backup (Even Months Later or on a New Server)&quot;">​</a></h2><ol><li>Sign in to WealthFam with an email address that belongs to the <strong>owner or any family member</strong> from the backup.</li><li>Open <strong>Settings → Backup &amp; Restore</strong>.</li><li>Drop or select your <code>.wfam</code> file and enter the <strong>Backup Passphrase</strong> (if encrypted).</li><li>Click <strong>Verify &amp; Preview</strong>: <ul><li>WealthFam decrypts the archive, validates its integrity, and displays the backup date, family name, record counts, and <strong>Email Verification</strong> status.</li><li>If your signed-in email does <strong>not</strong> match the owner or any family member in the backup, restore is blocked with a clear email mismatch error.</li></ul></li><li>Click <strong>Merge &amp; Restore Backup</strong>: <ul><li><strong>Priority-Preserving Merge</strong>: Existing data on the new server is <strong>never wiped or overwritten</strong>. Existing accounts, categories, budgets, transactions, holdings, settings, and email configurations on the new server take highest priority, while missing records from the backup are merged in with freshly generated IDs.</li><li>All sensitive fields and Vault documents are automatically re-encrypted under the new server&#39;s active Tenant Data Encryption Key (DEK).</li><li>Any family members from the backup who don&#39;t yet exist in the new workspace are recreated automatically so account/holding ownership is preserved; update their passwords in <strong>Settings → Family Circle</strong>.</li></ul></li></ol>',15)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
